package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen1Test {

    private static final double DELTA = 1e-12;

    @Test(expected = IllegalArgumentException.class)
    public void testFactorialLog_NegativeInput() {
        MathUtils.factorialLog(-1);
    }

    @Test
    public void testFactorialLog_Zero() {
        // factorial(0) is 1, log(1) is 0
        assertEquals(0.0, MathUtils.factorialLog(0), DELTA);
    }

    @Test
    public void testFactorialLog_One() {
        // factorial(1) is 1, log(1) is 0
        assertEquals(0.0, MathUtils.factorialLog(1), DELTA);
    }

    @Test
    public void testFactorialLog_SmallN() {
        // n < 21 branch: uses Math.log(factorial(n))
        // factorial(5) = 120
        assertEquals(Math.log(120.0), MathUtils.factorialLog(5), DELTA);
        // factorial(10) = 3628800
        assertEquals(Math.log(3628800.0), MathUtils.factorialLog(10), DELTA);
    }

    @Test
    public void testFactorialLog_BoundaryN20() {
        // n = 20 is the upper bound of the first branch (n < 21)
        double expected = Math.log(MathUtils.factorial(20));
        assertEquals(expected, MathUtils.factorialLog(20), DELTA);
    }

    @Test
    public void testFactorialLog_BoundaryN21() {
        // n = 21 enters the second branch (n >= 21)
        // logSum = log(2) + log(3) + ... + log(21)
        double expectedLogSum = 0;
        for (int i = 2; i <= 21; i++) {
            expectedLogSum += Math.log((double) i);
        }
        assertEquals(expectedLogSum, MathUtils.factorialLog(21), DELTA);
    }

    @Test
    public void testFactorialLog_LargeN() {
        // n > 21 branch
        int n = 50;
        double expectedLogSum = 0;
        for (int i = 2; i <= n; i++) {
            expectedLogSum += Math.log((double) i);
        }
        assertEquals(expectedLogSum, MathUtils.factorialLog(n), DELTA);
    }
}
